import pandas as pd

def clean(df):
    df = df.copy()
    num_cols = ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']
    for c in num_cols:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    if 'flipper_length_mm' in df.columns:
        neg = df['flipper_length_mm'] < 0
        df.loc[neg, 'flipper_length_mm'] = df.loc[neg, 'flipper_length_mm'].abs()
    if 'body_mass_g' in df.columns:
        def fix_mass(x):
            if pd.isna(x):
                return x
            x = float(x)
            while x > 6500 and x >= 10000 and x % 10 == 0:
                x /= 10
            return x
        df['body_mass_g'] = df['body_mass_g'].map(fix_mass)
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype('string').str.strip().str.lower()
        df.loc[df['sex'].isin(['', 'nan', 'none']), 'sex'] = pd.NA
    if 'species' in df.columns:
        df['species'] = df['species'].astype('string').str.strip()
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'body_mass_g'])
    totals = d.groupby('species', dropna=True)['body_mass_g'].sum()
    return {str(k): float(v) for k, v in totals.items()}
